Please suggest a completion for the following Python code to find the maximum sum of a path in a given binary tree.

```python
class Node:
    def __init__(self, data):
        self.left = None
        self.right = None
        self.data = data

def maxPathSum(node):
    if node is None:
        return 0
    else:
        leftSum = maxPathSum(node.left)
        rightSum = maxPathSum(node.right)
        maxSum = max(leftSum, rightSum) + node.data
        if node.left and node.right:
            maxSum = max(maxSum, leftSum + rightSum + node.data)
        return max(maxSum, node.data)
